div.script:
document.addEventListener('DOMContentLoaded', function() {
    var selectCompany = document.getElementById('select_company_id');
    var selectType = document.getElementById('select_room_type_id');
    var selectRoom = document.getElementById('select_room_id');
    if (!selectCompany || !selectType || !selectRoom) return;

    var allRooms = [];
    var initialOptions = selectRoom.querySelectorAll('option');
    initialOptions.forEach(function(opt) {
        if (opt.value) {
            allRooms.push({
                id: opt.value,
                companyId: opt.getAttribute('data-company'),
                typeId: opt.getAttribute('data-type'),
                text: opt.textContent.trim()
            });
        }
    });

    function filterRooms() {
        var compId = selectCompany.value;
        var typeId = selectType.value;
        var currentVal = selectRoom.value;

        selectRoom.innerHTML = '<option value="">-- Tự động xếp phòng trống tốt nhất --</option>';

        var matched = allRooms.filter(function(r) {
            return (!compId || r.companyId == compId) && (!typeId || r.typeId == typeId);
        });

        if (matched.length === 0) {
            var emptyOpt = document.createElement('option');
            emptyOpt.value = "";
            emptyOpt.disabled = true;
            emptyOpt.textContent = "(Chưa có phòng thuộc hạng phòng này)";
            selectRoom.appendChild(emptyOpt);
        } else {
            matched.forEach(function(r) {
                var opt = document.createElement('option');
                opt.value = r.id;
                opt.textContent = r.text;
                if (r.id === currentVal) {
                    opt.selected = true;
                }
                selectRoom.appendChild(opt);
            });
        }
    }

    selectCompany.addEventListener('change', filterRooms);
    selectType.addEventListener('change', filterRooms);
    filterRooms();
});
